const r1={id:"R001",inputs:["H002","H004","H005"],output:"N001",definitions:["D001"],rules:["direct","forall_introduction","exists_elimination"],locals:[
L("x","point of R^n","S001","S003","arbitrary","Fix an arbitrary x∈R^n.",[],[],["n"]),
L("t","positive real number","S001","S003","arbitrary","Fix an arbitrary t∈(0,∞)."),
L("a","real number","S002","S003","witness","At (x,t), choose a with u_tt-Δ_xu=a u, by H005.",["H005"],[],["u","x","t","Δ_x"])
],argument:[
S("S001","Fix arbitrary x∈R^n and t>0. By H004 the identity u(x,r)·u(x,r)=1 holds for every r>0. H002 permits differentiating this scalar identity in r at t. The ordinary product rule for the finite Euclidean dot product gives 2u(x,t)·u_t(x,t)=0, hence u·u_t=0 at (x,t).",["H002","H004"],[],["u","n","x","t"],[F("F001","u(x,t)·u_t(x,t)=0.",["u","x","t"])]),
S("S002","Choose a real scalar a at (x,t) from H005, so u_tt-Δ_xu=a u. Dot with u_t and use F001 and symmetry of the dot product: u_t·(u_tt-Δ_xu)=a(u_t·u)=0. This uses only a pointwise choice; no derivative or continuity of a is required.",["H005"],["F001"],["u","x","t","a","Δ_x"],[F("F002","u_t(x,t)·(u_tt(x,t)-Δ_xu(x,t))=0.",["u","x","t","Δ_x"])]),
S("S003","Retain also the supplied explicit-equation calculation. Twice differentiating u·u=1 in time, using H002 and H004, gives 2|u_t|^2+2u·u_tt=0. Twice differentiating the same identity in each spatial coordinate gives 2|∂_{x_j}u|^2+2u·∂_{x_jx_j}u=0 for every j=1,...,n. Thus u·u_tt=-|u_t|^2 and u·∂_{x_jx_j}u=-|∂_{x_j}u|^2. Dot the chosen normality equation with u. Since u·u=1, a=u·(u_tt-Δ_xu)=sum_{j=1}^n|∂_{x_j}u|^2-|u_t|^2. This computation applies to every scalar satisfying that equation at (x,t); substitute it back to obtain the explicit equation in N001. Together with F001 and F002 these are all clauses of N001. The point (x,t) was arbitrary, and the scalar witness's private identity does not occur in the resulting equation, so quantify over all x and t>0.",["H002","H004"],["F001","F002"],["u","n","x","t","a","Δ_x"])
],applications:[]};
const r2={id:"R002",inputs:["H001","H002","H006"],output:"N002",definitions:["D001","D002"],rules:["direct","forall_introduction","exists_elimination"],locals:[
L("t0","positive real number","S001","S004","arbitrary","Fix arbitrary t0>0."),
L("J","closed interval in R","S001","S004","definition","Set J=[t0/2,3t0/2].",[],[],["t0"]),
L("C","subset of R^n","S001","S004","witness","Choose compact C for the interval J as in H006.",["H006"],[],["n","J","u","q"]),
L("R","real number","S003","S004","witness","Choose R>0 with C⊂(-R,R)^n, as established in F002.",[],["F002"],["n","C"]),
L("Q","subset of R^n","S003","S004","definition","Set Q=[-R,R]^n.",[],[],["R","n"])
],argument:[
S("S001","Fix t0>0 and put J=[t0/2,3t0/2]. Then 0<t0/2<3t0/2<∞. Instantiate H006 with these endpoints and choose its compact C. Thus u(x,r)=q for every x outside C and every r∈J.",["H006"],[],["t0","J","C","n","u","q"],[F("F001","C is compact in R^n and u(x,r)=q for every x∉C and r∈J.",["C","u","q","n","J"],[b("x","point of R^n"),b("r","real number")])]),
S("S002","A compact subset of finite-dimensional Euclidean space is bounded: the open boxes (-k,k)^n for positive integers k cover R^n and form an increasing family; compactness gives a finite subcover of C and therefore one containing box. For C empty any positive radius works. Consequently there exists R>0 with C⊂(-R,R)^n. This also exhibits the needed room between C and the boundary of the closed box.",[],["F001"],["C","n"],[F("F002","There exists a real R>0 such that C⊂(-R,R)^n.",["C","n"],[b("R","real number, existentially quantified")])]),
S("S003","Choose R>0 from F002 and set Q=[-R,R]^n. H001 ensures a finite positive number n of spatial coordinates. Q is compact and has Lebesgue measure (2R)^n<∞ by the rectangle formula. Since compact C is closed, (R^n\\C)×int J is open. On that open set F001 says u is identically q. By H002 and locality of classical differentiation, every positive-order derivative of u is zero there: each component's difference quotients of a constant vanish, and this repeats for higher derivatives. Thus e,e_t and every derivative product listed in N002 vanish outside C at interior times.",["H001","H002"],["F001","F002"],["n","u","q","t0","J","C","R","Q","e"],[F("F003","Q=[-R,R]^n is compact with finite Lebesgue measure (2R)^n, C⊂int Q, and every positive-order derivative of u vanishes on (R^n\\C)×int J.",["Q","R","n","C","u","J"])]),
S("S004","Smoothness H002 makes e,e_t, u_t·u_tt, and, for each j=1,...,n, u_t·∂_{x_j}u, ∂_{x_j}u_t·∂_{x_j}u, u_t·∂_{x_jx_j}u and ∂_{x_j}(u_t·∂_{x_j}u) continuous on R^n×(0,∞). At any fixed r∈int J, each is continuous and hence Borel measurable as a function of space. Its absolute value attains a finite bound on compact Q, and it is zero outside C by F003. Thus its absolute integral on R^n is at most its finite bound times |Q|=(2R)^n, proving integrability. These conclusions hold for every r∈int J and each spatial index. In particular t0∈int J, so e(·,t0) is integrable. Since t0 was arbitrary, e(·,t) is integrable for every t>0. The witnesses C,R and their definitions J,Q establish exactly the existential window assertion of N002; none escapes as a globally fixed choice.",["H002"],["F001","F003"],["u","q","n","t0","J","C","R","Q","e"])
],applications:[]};
